import hashlib
import json
import logging
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
from typing import Optional

import dataiku
from dataiku.generated_sources.com.dataiku.dip.agents.tools.agent_tool.agent_tool import AgentTool
from dataiku.generated_sources.com.dataiku.dip.agents.tools.agent_tool_meta.subtool_descriptor import SubtoolDescriptor
from dataiku.generated_sources.com.dataiku.dip.agents.tools.agent_tool_meta.tool_descriptor import ToolDescriptor
from dataiku.generated_sources.com.dataiku.dip.dao.saved_model.block_graph_tool import BlockGraphTool
from dataiku.generated_sources.com.dataiku.dip.dao.saved_model.used_tool import UsedTool
from dataiku.generated_sources.com.dataiku.dip.llm.online.llm_client.function_tool import FunctionTool
from dataikuapi.dss.agent_tool import DSSAgentTool
from dataikuapi.dss.project import DSSProject

logger = logging.getLogger("dku.agents.tools_loader")

@dataclass
class BaseLLMTool:
    llm_tool_name: str
    llm_descriptor: FunctionTool


@dataclass
class LLMTool(BaseLLMTool):
    """
    This class encapsulates a lot of information:
        - the tool LLM-compatible definition
        - the Dataiku API tool interface
        - all Dataiku-specific data about the tool
    """
    dku_tool: DSSAgentTool
    dku_tool_ref: str
    dku_tool_name: str
    dku_tool_type: str
    dku_subtool_name: Optional[str]
    require_validation: bool
    allow_editing_inputs: bool


@dataclass
class ToolSpec:
    tool_ref: str
    additional_description: str
    # for selecting one specific sub-tool
    subtool_name: str
    # internally used for building the corresponding llm tool names
    spec_hash: str

    @staticmethod
    def _from_fields(
            tool_ref: str,
            additional_description: Optional[str] = None,
            subtool_name: Optional[str] = None
    ):
        additional_description = (additional_description or "").strip()
        subtool_name = (subtool_name or "").strip()
        # derive the unique tool spec hash from its fields
        fields = [tool_ref, additional_description, subtool_name]
        serialized_fields = json.dumps(fields, sort_keys=True, ensure_ascii=True)
        fields_hash = hashlib.sha256(serialized_fields.encode("utf-8")).hexdigest()[:6]
        return ToolSpec(tool_ref, additional_description, subtool_name, fields_hash)

    @staticmethod
    def from_used_tool(used_tool: UsedTool):
        return ToolSpec._from_fields(
            tool_ref=used_tool["toolRef"],
            additional_description=used_tool.get("additionalDescription")
        )

    @staticmethod
    def from_block_graph_tool(block_graph_tool: BlockGraphTool):
        # noinspection PyTypedDict
        # additionalDescription can be there for some BlockGraphTool subclasses
        return ToolSpec._from_fields(
            tool_ref=block_graph_tool["toolRef"],
            additional_description=block_graph_tool.get("additionalDescription"),
            subtool_name=block_graph_tool.get("subtoolName")
        )

    @staticmethod
    def from_tool_ref(tool_ref: str):
        return ToolSpec._from_fields(tool_ref=tool_ref)


@dataclass
class CachedTool:
    dku_api_tool: DSSAgentTool
    tool_descriptor: ToolDescriptor
    tool_params: AgentTool

    @staticmethod
    def load(tool_ref: str, project: DSSProject):
        """
        Fetches the tool parameters and descriptors, using the public API.
        Note that loading tool's descriptor can be costly: for instance, obtaining descriptor of Python inline tools requires spawning a Python process
        """
        logger.info(f"Loading tool {tool_ref}")
        dku_api_tool = project.get_agent_tool(tool_ref)
        tool_descriptor = dku_api_tool.get_descriptor()
        tool_params = dku_api_tool.get_settings().get_raw()
        return CachedTool(dku_api_tool, tool_descriptor, tool_params)


class ConcurrentToolsLoader:
    """
    This class is responsible for loading all tools used by the agents.
    Internally, it caches the result to avoid unnecessary IO during the same turn.
    Tools are loaded concurrently.
    """

    def __init__(self, max_workers: int):
        self._cache: dict[str, CachedTool] = dict()  # indexed by tool_ref
        self._project = dataiku.api_client().get_default_project()
        self._max_workers = max_workers

    @staticmethod
    def build(dku_properties: dict[str, str]):
        max_workers = _get_max_workers(dku_properties)
        logger.info(f"using {max_workers} workers to load agent tools")
        return ConcurrentToolsLoader(max_workers=max_workers)

    def load_tools(self, specs: list[ToolSpec]) -> list[LLMTool]:
        tool_refs = [spec.tool_ref for spec in specs]
        logger.info(f"Will use tools: {tool_refs}")

        specs_to_load = [
            spec for spec in specs
            if spec.tool_ref not in self._cache
        ]

        # load tools that are not cached yet
        if len(specs_to_load) == 1:
            # only one tool -> load directly (no need for a thread pool here)
            tool_ref = specs_to_load[0].tool_ref
            self._cache[tool_ref] = CachedTool.load(tool_ref, self._project)

        elif len(specs_to_load) > 1:
            # more than one tool -> load concurrently [sc-294535]
            with ThreadPoolExecutor(max_workers=self._max_workers) as executor:
                futures = [
                    executor.submit(CachedTool.load, spec.tool_ref, self._project)
                    for spec in specs_to_load
                ]

                for spec, future in zip(specs_to_load, futures):
                    self._cache[spec.tool_ref] = future.result()

        # all tools are cached by now
        all_llm_tools: list[LLMTool] = []
        for spec in specs:
            cached_tool = self._cache[spec.tool_ref]
            llm_tools = _build_llm_tools(spec, cached_tool)
            all_llm_tools.extend(llm_tools)

        return all_llm_tools


def _get_max_workers(dku_properties: dict[str, str]) -> int:
    key = "dku.agents.maxParallelToolLoadingExecutions"
    try:
        value = int(dku_properties.get(key, "8"))
    except ValueError as e:
        raise ValueError(f"Property {key} must be a positive number, cause: {e}")

    if value < 1:
        raise ValueError(f"Property {key} must be a positive number, got {value}")

    return value


def _build_llm_tools(spec: ToolSpec, cached_tool: CachedTool) -> list[LLMTool]:
    """
    Builds the LLM tools corresponding to the provided spec and cached info.
    When the tool has no sub-tools, the returned list has a length of 1.
    Otherwise, the list contains as many items as there are enabled sub-tools
    within this tool.

    Optionally, when the spec declares a subtool_name, it is used to filter
    the returned list to match only the subtool_name. An error is raised when
    there is no match.
    """
    dku_api_tool = cached_tool.dku_api_tool
    tool_descriptor = cached_tool.tool_descriptor
    tool_params = cached_tool.tool_params

    if not tool_descriptor.get("multiple", False):
        llm_tool = _build_single_llm_tool(
            spec, dku_api_tool,
            tool_params, tool_descriptor
        )
        return [llm_tool]

    # multiple sub-tools
    llm_tools: list[LLMTool] = []
    for subtool_descriptor in tool_descriptor.get("subtools", []):
        if not subtool_descriptor.get("enabled", False):
            continue  # ignore disabled sub-tool

        if spec.subtool_name and subtool_descriptor["name"] != spec.subtool_name:
            continue  # ignore other sub-tool

        llm_tool = _build_single_llm_tool(
            spec, dku_api_tool,
            tool_params, tool_descriptor,
            subtool_descriptor
        )
        llm_tools.append(llm_tool)

    if spec.subtool_name and not llm_tools:
        raise ValueError(
            f"No enabled subtool named {spec.subtool_name} "
            f"within tool {spec.tool_ref}"
        )

    return llm_tools


def _build_single_llm_tool(
        spec: ToolSpec,
        dku_api_tool: DSSAgentTool,
        tool_params: AgentTool,
        tool_descriptor: ToolDescriptor,
        subtool_descriptor: Optional[SubtoolDescriptor] = None
):
    llm_tool_name = "{}__{}".format(
        tool_descriptor["name"],
        spec.spec_hash
    )

    if subtool_descriptor:
        dku_subtool_name = subtool_descriptor["name"]
        description = subtool_descriptor.get("description", "")
        schema = subtool_descriptor["inputSchema"]
        llm_tool_name += "__" + dku_subtool_name
    else:
        dku_subtool_name = None
        description = tool_descriptor.get("description", "")
        schema = tool_descriptor["inputSchema"]

    return LLMTool(
        llm_tool_name=llm_tool_name,
        llm_descriptor={
            "type": "function",
            "function": {
                "name": llm_tool_name,
                "description": "{}\n\n{}".format(
                    description,
                    spec.additional_description
                ).strip(),
                "parameters": schema
            }
        },
        dku_tool=dku_api_tool,
        dku_tool_ref=spec.tool_ref,
        dku_tool_name=tool_params["name"],
        dku_tool_type=tool_params["type"],
        dku_subtool_name=dku_subtool_name,
        require_validation=tool_params["requireHumanApproval"],
        allow_editing_inputs=tool_params["allowEditingInputs"],
    )
